import { tags } from "typia";

import { IPage } from "./IPage";
import { IShoppingMallOrderItem } from "./IShoppingMallOrderItem";

/**
 * Aggregated order item statistics response for seller dashboard analytics. Provides comprehensive metrics including total item counts, pending cancellation/refund request counts, status distribution breakdown, quantity and value totals, pagination metadata, and paginated item list. Used by sellers to monitor fulfillment workload and business performance.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallOrderItemStat = {
  /**
   * Total count of order items matching the filter criteria. Each order item represents one product variant purchase line in an order.
   *
   * @x-autobe-specification Computed as COUNT(*) from shopping_mall_order_items WHERE shopping_mall_seller_id = current authenticated seller AND matches all filter criteria from IShoppingMallOrderItem.IRequest (status array, date range, product ID, etc.). This count represents the total number of order item records matching the query, not the sum of quantities.
   */
  totalItems: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of order items with pending cancellation requests awaiting seller response. Sellers must review and approve/reject these requests.
   *
   * @x-autobe-specification Computed as COUNT of shopping_mall_order_items that have at least one pending cancellation request. Query: COUNT(DISTINCT oi.id) FROM shopping_mall_order_items oi LEFT JOIN shopping_mall_cancellation_requests cr ON cr.shopping_mall_order_item_id = oi.id WHERE oi.shopping_mall_seller_id = current seller AND cr.status = 'pending' AND matches other filters. Only counts items with cancellation requests in 'pending' status awaiting seller response.
   */
  pendingCancellations: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of order items with pending refund requests awaiting seller response. Sellers must review and approve/reject these requests for delivered items.
   *
   * @x-autobe-specification Computed as COUNT of shopping_mall_order_items that have at least one pending refund request. Query: COUNT(DISTINCT oi.id) FROM shopping_mall_order_items oi LEFT JOIN shopping_mall_refund_requests rr ON rr.shopping_mall_order_item_id = oi.id WHERE oi.shopping_mall_seller_id = current seller AND rr.status = 'pending' AND matches other filters. Only counts items with refund requests in 'pending' status awaiting seller response.
   */
  pendingRefunds: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Distribution of order items by status. Shows count of items in each lifecycle stage: paid (awaiting shipment), shipped (in transit), delivered (received by customer), cancelled (cancelled before shipping), and refunded (refunded after delivery).
   *
   * @x-autobe-specification Computed as GROUP BY status with COUNT aggregation. Query: SELECT status, COUNT(*) as count FROM shopping_mall_order_items WHERE shopping_mall_seller_id = current seller AND matches filter criteria GROUP BY status. Returns object with keys 'paid', 'shipped', 'delivered', 'cancelled', 'refunded' and integer count values. Status values follow order lifecycle: paid (awaiting shipment), shipped (in transit), delivered (received), cancelled (cancelled before shipping), refunded (refunded after delivery).
   */
  statusBreakdown: {
    paid: number & tags.Type<"int32"> & tags.Minimum<0>;
    shipped: number & tags.Type<"int32"> & tags.Minimum<0>;
    delivered: number & tags.Type<"int32"> & tags.Minimum<0>;
    cancelled: number & tags.Type<"int32"> & tags.Minimum<0>;
    refunded: number & tags.Type<"int32"> & tags.Minimum<0>;
  };

  /**
   * Total number of product units across all matching order items. Sum of individual item quantities, representing the actual count of products sold.
   *
   * @x-autobe-specification Computed as SUM(quantity) from shopping_mall_order_items WHERE shopping_mall_seller_id = current seller AND matches filter criteria. Aggregates the quantity field across all matching order items to show total number of product units across all filtered orders. Different from totalItems which counts order item records.
   */
  totalQuantity: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total monetary value of all matching order items. Calculated as sum of (quantity × unit_price) for each item, representing total sales value.
   *
   * @x-autobe-specification Computed as SUM(quantity * unit_price) from shopping_mall_order_items WHERE shopping_mall_seller_id = current seller AND matches filter criteria. Calculates total monetary value by multiplying each item's quantity by its unit_price snapshot value and summing across all matching items. Returns decimal/number for monetary precision.
   */
  totalValue: number & tags.Minimum<0>;

  /**
   * Pagination metadata for the filtered order items list. Contains current page number, items per page limit, total record count, and total page count.
   *
   * @x-autobe-specification Computed from the same COUNT query used for totalItems. Constructs IPage.IPagination object with: current (requested page number, 1-indexed), limit (requested limit, max 100), records (totalItems count), pages (Math.ceil(records / limit)). Provides standard pagination metadata for the data array.
   */
  pagination: IPage.IPagination;

  /**
   * Paginated list of order items matching the filter criteria. Each item contains snapshot data (product name, variant SKU, seller shop name, pricing) captured at purchase time for historical accuracy.
   *
   * @x-autobe-specification Paginated array of IShoppingMallOrderItem.ISummary objects fetched from shopping_mall_order_items. Query: SELECT fields FROM shopping_mall_order_items WHERE shopping_mall_seller_id = current seller AND matches filter criteria ORDER BY sort criteria (default: created_at DESC) LIMIT limit OFFSET (page-1)*limit. Each item transformed to ISummary format including JOINs to shopping_mall_orders for order context and shopping_mall_order_item_variant_options for variant options array.
   */
  data: IShoppingMallOrderItem.ISummary[];
};
